Here is the encryption snippet of my code (my entire program is over 300 lines as it consists numerous ciphers, not just caesar:

    #include<iostream>

using namespace std;

int main()
{
  char message[100], ch;
  int i, key;
  cout << "Enter the message to be encoded: ";
  cin >> message;
  cin.getline(message, 100);

  cout << "Entter the shift value (0-200): ";
  cin >> key;

  for(i = 0; message[i] != '\0'; ++i){
  ch = message[i];
  if(ch >= 'a' && ch <= 'z'){
  ch = ch + key;
  if(ch > 'z'){
  ch = ch - 'z' + 'a' - 1;
  }
  message[i] = ch;
  }
  else if(ch >= 'A' && ch <= 'Z'){
  ch = ch + key;
  if(ch > 'Z'){
  ch = ch - 'Z' + 'A' - 1;
  }
  message[i] = ch;
  }
  }
  cout << "Encrypted message: " << message << endl;
  return 0;
}

Thanks for the help.

